&gt; &lt;span class="hidden" data-render-id="quarto-breadcrumbs-8ad684dfa41ca7f3c5791d71c50c0073"&gt;&lt;span class="chapter-number"&gt;4&lt;/span&gt;  &lt;span class="chapter-title"&gt;ATAC-seq peak calling and visualization&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
